use vstd::prelude::*;

verus! {

    // In-place removal of all occurrences of `val` from `nums`.
    // Returns the number of elements remaining at the front of `nums`
    // such that for all k < returned length, nums[k] != val.
    //
    // There are no preconditions on `nums` or `val`.  After the call,
    // the vector length (`nums.len()`) is unchanged, but the first
    // `ret` entries are guaranteed not to equal `val`.
    fn removeElement(nums: &mut Vec<i32>, val: i32) -> (ret: usize)
        ensures
            // We never claim to shrink the Vec; ret is at most the original length.
            ret <= old(nums@).len(),
            // For every index in the retained prefix, the element is not `val`.
            forall |k: usize| k < ret ==> nums@[k] != val,
    {
        let n = nums.len();
        let mut w: usize = 0; // write‐pointer: next position to keep a non‐val
        let mut r: usize = 0; // read‐pointer: scans through 0..n

        while r < n
            invariant
                // pointers stay in bounds
                r <= n,
                w <= n,
                // write‐pointer never surpasses read‐pointer
                w <= r,
                // invariant: the first w elements are all ≠ val
                forall |k: usize| k < w ==> nums@[k] != val,
            decreases n - r,
        {
            if nums[r] != val {
                // safe because r < n and w <= r < n
                let x = nums[r];
                nums[w] = x;
                w += 1;
            }
            r += 1;
        }

        ret = w;
    }
}

